/** Adapted CC0 stereo park and evening recordings. Credits in ATTRIBUTION.txt. */
const decode=(base64,rate)=>{const bytes=Uint8Array.from(atob(base64),c=>c.charCodeAt(0)),view=new DataView(bytes.buffer),frames=bytes.length/4,left=new Float32Array(frames),right=new Float32Array(frames);for(let i=0;i<frames;i++){left[i]=view.getInt16(i*4,true)/32768;right[i]=view.getInt16(i*4+2,true)/32768;}return {left,right,rate};};
export const AMBIENT_KIT={
  birds:decode('',16000),
  crickets:decode('',16000)
};
